      await refreshProfile();
      toast.success(`Inbox regenerated: ${data}`);
    } catch (e: any) {
      toast.error(e.message || "Failed to regenerate inbox");
    } finally {
      setRegenerating(false);
    }
  };

  const handleToggleEmail = async (checked: boolean) => {
    if (!user) return;
    setTogglingEmail(true);
    const { error } = await supabase
      .from("profiles")
      .update({ email_enabled: checked })
      .eq("user_id", user.id);
    if (error) {
      toast.error(error.message);
