-- 2. Replace handle_new_user() with human-readable inbox email
CREATE OR REPLACE FUNCTION public.handle_new_user()
  RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
DECLARE
  raw_email text;
  local_part text;
  domain text;
  base_inbox text;
  final_inbox text;
  suffix text;
  attempts int := 0;
BEGIN
  -- Get user email
  raw_email := lower(trim(NEW.raw_user_meta_data->>'email'));
  IF raw_email IS NULL OR raw_email = '' THEN
    raw_email := lower(trim(NEW.email));
  END IF;

  -- Get inbound domain from config
  SELECT inbound_email_domain INTO domain FROM public.platform_config LIMIT 1;
  IF domain IS NULL OR domain = '' THEN
    domain := 'inbound.rankora.co';
  END IF;

  -- Extract and sanitize local part (before @)
  local_part := split_part(raw_email, '@', 1);
  -- Replace any char that isn't alphanumeric, dot, or hyphen
  local_part := regexp_replace(local_part, '[^a-z0-9.\-]', '.', 'g');
  -- Collapse consecutive dots
  local_part := regexp_replace(local_part, '\.{2,}', '.', 'g');
  -- Trim leading/trailing dots
  local_part := trim(both '.' from local_part);

  IF local_part = '' THEN
    local_part := 'user';
  END IF;

  base_inbox := local_part || '@' || domain;
  final_inbox := base_inbox;

  -- Check for collisions
  WHILE EXISTS (SELECT 1 FROM public.profiles WHERE inbox_email = final_inbox) LOOP
    attempts := attempts + 1;
    suffix := substr(md5(random()::text), 1, 3);
    final_inbox := local_part || '.' || suffix || '@' || domain;
    IF attempts > 10 THEN
      -- Fallback to full random
      final_inbox := substr(md5(NEW.id::text || now()::text), 1, 12) || '@' || domain;
      EXIT;
    END IF;
  END LOOP;

  INSERT INTO public.profiles (user_id, credits, inbox_email)
  VALUES (NEW.id, 5, final_inbox);

  INSERT INTO public.user_roles (user_id, role)
  VALUES (NEW.id, 'user');

  RETURN NEW;
END;
$function$;

-- 3. Replace generate_job_inbox_email() with human-readable format
CREATE OR REPLACE FUNCTION public.generate_job_inbox_email()
  RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
DECLARE
  user_inbox text;
  domain text;
  local_part text;
  short_id text;
BEGIN
  -- Get the job owner's inbox email
  SELECT inbox_email INTO user_inbox FROM public.profiles WHERE user_id = NEW.user_id;

  -- Get inbound domain from config
  SELECT inbound_email_domain INTO domain FROM public.platform_config LIMIT 1;
  IF domain IS NULL OR domain = '' THEN
    domain := 'inbound.rankora.co';
  END IF;

  IF user_inbox IS NOT NULL AND user_inbox LIKE '%@%' THEN
    local_part := split_part(user_inbox, '@', 1);
  ELSE
    local_part := substr(md5(NEW.user_id::text), 1, 8);
  END IF;

  -- Use first 8 chars of job ID as short identifier
  short_id := substr(NEW.id::text, 1, 8);
  NEW.inbox_email := local_part || '+j-' || short_id || '@' || domain;

  RETURN NEW;
END;
$function$;

-- 4. Create a reusable function for generating/regenerating user inbox
CREATE OR REPLACE FUNCTION public.generate_user_inbox_email(p_user_id uuid)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
DECLARE
  raw_email text;
  local_part text;
  domain text;
  base_inbox text;
  final_inbox text;
  suffix text;
  attempts int := 0;
BEGIN
  -- Get user email from auth.users
  SELECT lower(trim(email)) INTO raw_email FROM auth.users WHERE id = p_user_id;
  IF raw_email IS NULL OR raw_email = '' THEN
    raw_email := 'user' || substr(md5(p_user_id::text), 1, 6);
  END IF;

  -- Get inbound domain
  SELECT inbound_email_domain INTO domain FROM public.platform_config LIMIT 1;
  IF domain IS NULL OR domain = '' THEN
    domain := 'inbound.rankora.co';
  END IF;

  -- Sanitize local part
  local_part := split_part(raw_email, '@', 1);
  local_part := regexp_replace(local_part, '[^a-z0-9.\-]', '.', 'g');
  local_part := regexp_replace(local_part, '\.{2,}', '.', 'g');
  local_part := trim(both '.' from local_part);
  IF local_part = '' THEN local_part := 'user'; END IF;

  base_inbox := local_part || '@' || domain;
  final_inbox := base_inbox;

  -- Collision check (exclude current user)
  WHILE EXISTS (SELECT 1 FROM public.profiles WHERE inbox_email = final_inbox AND user_id != p_user_id) LOOP
    attempts := attempts + 1;
    suffix := substr(md5(random()::text), 1, 3);
    final_inbox := local_part || '.' || suffix || '@' || domain;
    IF attempts > 10 THEN
      final_inbox := substr(md5(p_user_id::text || now()::text), 1, 12) || '@' || domain;
      EXIT;
    END IF;
  END LOOP;

  -- Update profile
  UPDATE public.profiles SET inbox_email = final_inbox, updated_at = now() WHERE user_id = p_user_id;

  RETURN final_inbox;
END;
$function$;

-- 5. Re-attach trigger for jobs (ensure it exists)
DROP TRIGGER IF EXISTS trg_generate_job_inbox ON public.jobs;
CREATE TRIGGER trg_generate_job_inbox
  BEFORE INSERT ON public.jobs
  FOR EACH ROW
  WHEN (NEW.inbox_email IS NULL)
  EXECUTE FUNCTION public.generate_job_inbox_email();

