// ─── Health Alert Banner ───
function HealthBanner({ health, loading, onVerify }: {
  health: ResendHealth | null;
  loading: boolean;
  onVerify: () => void;
}) {
  if (loading) {
    return (
      <div className="rounded-lg border border-border bg-muted/30 p-4 flex items-center gap-3">
        <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
        <span className="text-sm text-muted-foreground">Checking Resend connection...</span>
      </div>
    );
  }

  if (!health) return null;

  const issues: { icon: React.ElementType; text: string; severity: "error" | "warning" }[] = [];

  if (!health.keyValid) {
    issues.push({ icon: XCircle, text: "API key is invalid or not configured", severity: "error" });
  }
  if (health.keyValid && !health.domainVerified) {
    issues.push({
      icon: AlertTriangle,
      text: `Domain for "${health.fromEmail}" is not verified in Resend. Emails will fail.`,
      severity: "warning",
    });
  }

  if (issues.length === 0 && health.keyValid) {
    return (
      <div className="rounded-lg border border-green-200 bg-green-50 dark:border-green-900 dark:bg-green-950/50 p-4 space-y-2">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <CheckCircle2 className="h-4 w-4 text-green-600" />
            <span className="text-sm font-medium text-green-700 dark:text-green-400">
              Resend Connected{health.domainName ? ` — ${health.domainName}` : ""}
            </span>
          </div>
          <Button variant="ghost" size="sm" className="gap-1.5 h-7 text-xs" onClick={onVerify}>
            <RefreshCw className="h-3 w-3" /> Recheck
          </Button>
        </div>
        <div className="flex gap-3 text-xs text-green-600 dark:text-green-500">
          <span className="flex items-center gap-1"><CheckCircle2 className="h-3 w-3" /> API key valid</span>
          <span className="flex items-center gap-1"><CheckCircle2 className="h-3 w-3" /> Domain verified</span>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-2">
      {issues.map((issue, i) => (
        <div
          key={i}
          className={`rounded-lg border p-3 flex items-start gap-2 ${
            issue.severity === "error"
              ? "border-destructive/50 bg-destructive/10 text-destructive"
              : "border-amber-200 bg-amber-50 dark:border-amber-900 dark:bg-amber-950 text-amber-700 dark:text-amber-400"
          }`}
        >
          <issue.icon className="h-4 w-4 shrink-0 mt-0.5" />
          <p className="text-xs">{issue.text}</p>
        </div>
      ))}
      <div className="flex justify-end">
        <Button variant="ghost" size="sm" className="gap-1.5 h-7 text-xs" onClick={onVerify}>
          <RefreshCw className="h-3 w-3" /> Recheck
        </Button>
      </div>
    </div>
  );
}

